fibMemo(n, memo) BEGIN
  IF (n <= 1) THEN BEGIN
    RETURN n;
  END
  IF (memo[n] != -1) THEN BEGIN
    RETURN memo[n];
  END
  memo[n] <- fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  RETURN memo[n];
END

