seleccionarActividades(inicio[n], fin[n], n) BEGIN
  ordenarPorFin(inicio, fin, n);
  seleccionadas <- 0;
  ultimoFin <- -1;
  FOR i <- 1 TO n DO BEGIN
    IF (inicio[i] >= ultimoFin) THEN BEGIN
      seleccionadas <- seleccionadas + 1;
      ultimoFin <- fin[i];
    END
  END
  RETURN seleccionadas;
END

buscar(k) BEGIN
  IF (k = n) THEN BEGIN
    imprimir(solucion);
    RETURN 0;
  END
  FOR candidato <- 1 TO n DO BEGIN
    IF (esValido(candidato)) THEN BEGIN
      agregar(solucion, candidato);
      buscar(k + 1);
    END
  END
  RETURN 0;
END

generar(pos, n) BEGIN
  IF (pos > n) THEN BEGIN
    imprimir(solucion);
    RETURN 0;
  END
  FOR candidato <- 1 TO n DO BEGIN
    IF (noUsado[candidato]) THEN BEGIN
      solucion[pos] <- candidato;
      noUsado[candidato] <- false;
      generar(pos + 1, n);
      noUsado[candidato] <- true;
    END
  END
  RETURN 0;
END

resolver(A, l, r) BEGIN
  IF (l = r) THEN BEGIN
    RETURN A[l];
  END
  m <- (l + r) / 2;
  x <- resolver(A, l, m);
  y <- resolver(A, m + 1, r);
  RETURN combinar(x, y);
END

resolver(n) BEGIN
  IF (n = 0) THEN BEGIN
    RETURN 1;
  END
  parcial <- resolver(n - 1);
  RETURN ajustar(parcial, n);
END

buscar(pos) BEGIN
  IF (pos > n) THEN BEGIN
    imprimir(solucion);
    RETURN 0;
  END
  FOR candidato <- 1 TO n DO BEGIN
    IF (factible(pos, candidato)) THEN BEGIN
      solucion[pos] <- candidato;
      buscar(pos + 1);
      solucion[pos] <- 0;
    END
  END
  RETURN 0;
END

optimizar(nodo) BEGIN
  IF (noFactible(nodo)) THEN BEGIN
    RETURN 0;
  END
  IF (cota(nodo) <= mejorValor) THEN BEGIN
    RETURN 0;
  END
  IF (esSolucionCompleta(nodo)) THEN BEGIN
    actualizarMejor(nodo);
    RETURN 0;
  END
  hijos <- expandir(nodo);
  FOR i <- 1 TO longitud(hijos) DO BEGIN
    optimizar(hijos[i]);
  END
  RETURN 0;
END

calcular(n) BEGIN
  IF (n <= 1) THEN BEGIN
